import * as THREE from 'three/webgpu';
import { texture, uv, vec4, mix, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-headline';

  const pos = config.scenePosition || { x: 0, y: 3, z: 0 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const width = 5.5;
  const height = 5.5 * (320 / 512);

  const planeGeo = new THREE.PlaneGeometry(width, height);
  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });

  let map = null;
  const imageUrl = '/prism-mock/home/nodes/feature-card.png';
  if (ctx.textureLoader) {
    try {
      map = ctx.textureLoader.load(imageUrl);
      map.colorSpace = THREE.SRGBColorSpace;
    } catch (e) {
      map = null;
    }
  }

  if (map) {
    const texNode = texture(map, uv());
    const inkColor = vec4(
      new THREE.Color(colors.ink).r,
      new THREE.Color(colors.ink).g,
      new THREE.Color(colors.ink).b,
      1.0
    );
    const gradFactor = uv().y;
    const gradColor = mix(inkColor, texNode, gradFactor.mul(0.6).add(0.4));
    material.colorNode = mix(texNode, gradColor, float(0.35));
    material.opacityNode = texNode.a;
  } else {
    material.colorNode = vec4(
      new THREE.Color(colors.surface).r,
      new THREE.Color(colors.surface).g,
      new THREE.Color(colors.surface).b,
      1.0
    );
  }

  const planeMesh = new THREE.Mesh(planeGeo, material);
  planeMesh.name = 'home-headline-plane';
  group.add(planeMesh);

  // Render text content via MSDF font atlas
  const textContent = config.textContent || [
    { role: 'body', text: 'A machined-metal watch atelier landing with catalog, pricing, jo', size: 31, weight: 400 }
  ];

  const textMeshes = [];
  let cursorY = -height / 2 + 0.3;

  textContent.forEach((entry, idx) => {
    const str = typeof entry === 'string' ? entry : entry.text;
    const role = typeof entry === 'object' && entry.role ? entry.role : 'body';
    const weight = typeof entry === 'object' && entry.weight ? entry.weight : 400;

    const scaleMap = {
      hero: 0.62,
      headline: 0.34,
      subhead: 0.2,
      body: 0.13,
      caption: 0.09
    };
    const emSize = scaleMap[role] || 0.13;

    let textMesh = null;
    try {
      textMesh = ctx.fontAtlas.createTextMesh({
        text: str,
        font: 'JetBrains Mono',
        weight,
        size: emSize,
        color: colors.paper,
        maxWidth: width * 0.85,
        align: 'left'
      });
    } catch (e) {
      textMesh = null;
    }

    if (textMesh) {
      textMesh.position.set(-width / 2 + 0.25, cursorY + idx * 0.05, 0.01);
      textMesh.name = `home-headline-text-${idx}`;
      group.add(textMesh);
      textMeshes.push(textMesh);
    }
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    planeGeo.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    textMeshes.forEach((textMesh) => {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) {
        if (Array.isArray(textMesh.material)) {
          textMesh.material.forEach((m) => m.dispose());
        } else {
          textMesh.material.dispose();
        }
      }
    });
  };

  return group;
}
